document.addEventListener("DOMContentLoaded",(function(){var e=document.querySelectorAll(".rpt-lazyload, .lazy-load");if("IntersectionObserver"in window){var a=new IntersectionObserver((function(e,a){e.forEach((function(e){if(e.isIntersecting){var t=e.target;if(t.classList.contains("rpt-lazyload")){var n=t.dataset.bg;t.style.backgroundImage="url("+n+")"}else t.classList.contains("lazy-load")&&(n=t.dataset.src,t.src=n);t.classList.remove("rpt-lazyload","lazy-load"),a.unobserve(t)}}))}));e.forEach((function(e){a.observe(e)}))}}));